begin;
select plan(23);
select has_function('public','public_assistant_commit_index',array['uuid','uuid','jsonb','jsonb','jsonb'],'atomic fenced index commit exists');
select ok(not has_table_privilege('service_role','public.public_assistant_sources','UPDATE'),'legacy worker cannot change staging or publication');
select ok(not has_table_privilege('service_role','public.public_assistant_chunks','DELETE'),'legacy worker cannot delete newer chunks');
select ok(not has_table_privilege('service_role','public.public_assistant_chunks','INSERT'),'legacy worker cannot insert stale chunks');
select ok(not has_table_privilege('service_role','public.public_assistant_document_text','UPDATE'),'legacy worker cannot overwrite extracted text');
select ok(not has_table_privilege('service_role','public.public_assistant_document_pages','DELETE'),'legacy worker cannot delete newer pages');
select ok(not has_table_privilege('service_role','public.public_assistant_index_jobs','UPDATE'),'worker cannot forge lease ownership');
select ok(not has_function_privilege('service_role','public.public_assistant_finish_index_job(uuid,uuid,uuid)','EXECUTE'),'legacy activation is not exposed to worker');
select ok(not exists(select 1 from pg_proc where oid=to_regprocedure('public.public_assistant_commit_index(uuid,uuid,jsonb,jsonb,jsonb)') and has_function_privilege('authenticated',oid,'EXECUTE')),'authenticated cannot commit privileged index');
insert into cms_pages(id,slug,title,body,status) values('sec18-sql','sec18-sql','SQL fixture','Original body','Published');
create temporary table sec18_ctx as select id,gen_random_uuid() token,source_version from public_assistant_index_jobs where source_key='sec18-sql';
update public_assistant_index_jobs set state='processing',attempt_count=1,lease_token=(select token from sec18_ctx),lease_expires_at=clock_timestamp()+interval '3 minutes' where id=(select id from sec18_ctx);
create function pg_temp.sec18_commit(token uuid, source_key text default 'sec18-sql') returns boolean language plpgsql as $$
begin return public.public_assistant_commit_index((select id from sec18_ctx),token,jsonb_build_object('type','page','key',source_key,'version',(select source_version from sec18_ctx),'title','SQL fixture','url','/sec18-sql','hash','fixture','model','mock','tokens',1),jsonb_build_array(jsonb_build_object('ordinal',0,'content','Original body','embedding',to_jsonb(array[1]||array_fill(0,array[1535])))),null);end;$$;
select lives_ok($$do $b$ begin if pg_temp.sec18_commit(gen_random_uuid()) then raise exception 'stale token accepted'; end if; end; $b$; $$,'wrong lease cannot commit');
select lives_ok($$do $b$ begin if pg_temp.sec18_commit((select token from sec18_ctx),'foreign-source') then raise exception 'foreign source accepted'; end if; end; $b$; $$,'cross-source payload cannot commit');
update public_assistant_index_jobs set lease_expires_at=clock_timestamp()-interval '1 second' where id=(select id from sec18_ctx);
select lives_ok($$do $b$ begin if pg_temp.sec18_commit((select token from sec18_ctx)) then raise exception 'expired lease accepted'; end if; end; $b$; $$,'expired lease cannot commit');
update public_assistant_index_jobs set lease_expires_at=clock_timestamp()+interval '3 minutes' where id=(select id from sec18_ctx);
select lives_ok($$select pg_temp.sec18_commit((select token from sec18_ctx))$$,'current owner commits');
select is((select count(*)::integer from public_assistant_sources where source_key='sec18-sql' and publication_status='published'),1,'owned batch published');
select is((select count(*)::integer from public_assistant_usage_events where request_key=(select id::text from sec18_ctx)),1,'usage settled exactly once');
select is((select count(*)::integer from public_assistant_chunks c join public_assistant_sources s on c.source_id=s.id where s.source_key='sec18-sql'),1,'one complete vector batch');
select lives_ok($$do $b$ begin if pg_temp.sec18_commit((select token from sec18_ctx)) then raise exception 'duplicate commit accepted'; end if; end; $b$; $$,'completed job cannot commit twice');
select lives_ok($$do $b$ begin if public_assistant_fail_index_job((select id from sec18_ctx),(select token from sec18_ctx),'late') then raise exception 'late failure accepted'; end if; end; $b$; $$,'late failure cannot revert completion');
select lives_ok($$do $b$ begin if public_assistant_cancel_index_job((select id from sec18_ctx),(select token from sec18_ctx)) then raise exception 'late cancellation accepted'; end if; end; $b$; $$,'late cancellation cannot revert completion');
set local role service_role;
select throws_ok($$delete from public_assistant_chunks$$,'42501',null,'direct stale cleanup denied');
select throws_ok($$update public_assistant_sources set publication_status='staged'$$,'42501',null,'direct publication downgrade denied');
reset role;
update public_assistant_index_jobs set state='processing',attempt_count=3,lease_expires_at=clock_timestamp()-interval '1 second' where id=(select id from sec18_ctx);
select lives_ok($$select public_assistant_claim_index_job()$$,'crash recovery remains callable');
select is((select state from public_assistant_index_jobs where id=(select id from sec18_ctx)),'failed','crashed third attempt becomes terminal');
select * from finish();
rollback;
